for(let [a,b] of [[[-62,5.8,12],[-63,5.8,27]],[[-63,5.8,27],[-54,5.8,31]],[[-54,5.8,31],[-43,5.8,29]],[[3,5.1,32],[10,5.1,46]],[[26,5.8,46],[41,5.8,52]]]){for(let p of [a,b])rod([p[0],1.35,p[2]],p,.073,L.iron);festoon(a,b);}
