// A small rowing dock and moored skiffs give the pond an edge to explore.
for(let i=0;i<18;i++)box(.44,.13,2.7,71+i*.43,1.65,38,M.wood);for(let x of [71.4,75.3,78])for(let z of [36.8,39.2])rod([x,1.3,z],[x,2.25,z],.08,L.trunk);
for(let [x,z,a] of [[65.3,42,.6],[68.3,43.3,-.35]]){const boat=new T.Group();boat.position.set(x,1.59,z);boat.rotation.y=a;land.add(boat);const hull=mesh(new T.SphereGeometry(1,12,6,0,TAU,0,PI/2),L.cream,0,0,0,boat);hull.rotation.x=PI;hull.scale.set(.62,.35,1.8);box(.72,.10,2.7,0,-.05,0,M.wood,boat,.03);for(let zz of [-.65,.5])box(1.07,.08,.35,0,.12,zz,L.iron,boat);rod([-.7,.17,-.8],[.75,.17,.7],.045,M.woodEdge,boat);}

