for(let [key,b] of batches){const inst=new T.InstancedMesh(b.geo,b.material,b.arr.length);for(let i=0;i<b.arr.length;i++){const a=b.arr[i];dummy.position.set(...a.pos);dummy.scale.set(...a.scale);dummy.rotation.set(...a.rot);dummy.updateMatrix();inst.setMatrixAt(i,dummy.matrix);if(a.color)inst.setColorAt(i,tmpColor.set(a.color));}inst.castShadow=key==='ties'||key==='new-foliage'||key==='trestle-legs';inst.receiveShadow=true;land.add(inst);}
consolidate(land,null);consolidateWires(land);
await step('Putting the trains into service…');
// The moving stock is built after static consolidation: six silver subway cars and a local train.
function trainCar(type,lead=false,index=0){const car=new T.Group();const silver=mat(type==='subway'?'#b9c3bb':'#ead9b8',{metalness:type==='subway'?.38:.12,roughness:.54});const trim=type==='subway'?M.navy:L.red;const w=type==='subway'?2.55:2.37,len=type==='subway'?7.2:6.35;
box(w,1.86,len,0,1.68,0,silver,car,.15);box(w+.02,.34,len-.18,0,2.65,0,silver,car,.12);box(w+.045,.22,len-.21,0,1.05,0,trim,car,.06);box(w-.14,.25,len-.14,0,.62,0,M.dark,car,.07);for(let end of [-1,1]){box(.45,.16,.5,0,.58,end*(len/2+.12),M.dark,car);for(let side of [-1,1]){const wheel=mesh(new T.CylinderGeometry(.32,.32,.16,14),M.dark,side*.95,.34,end*2.17,car);wheel.rotation.z=PI/2;const cap=mesh(new T.CylinderGeometry(.12,.12,.175,10),L.rail,side*.958,.34,end*2.17,car);cap.rotation.z=PI/2;}box(1.95,.35,1.35,0,.51,end*2.17,M.dark,car,.055);}
for(let side of [-1,1]){for(let z of [-2.63,-1.36,0,1.36,2.63]){const ww=z===0?.85:.83;box(.09,.94,ww,side*(w/2+.015),1.99,z,M.dark,car,.022);box(.035,.76,ww-.12,side*(w/2+.069),2.015,z,index%3===1?M.glass:windowMat,car,.012);if(z===0)box(.035,.85,.035,side*(w/2+.09),1.98,z,L.rail,car);}for(let z of [-1.95,1.95]){box(.046,1.65,.68,side*(w/2+.047),1.60,z,L.rail,car,.02);box(.047,.73,.54,side*(w/2+.08),2.02,z,M.glass,car,.01);box(.05,1.53,.024,side*(w/2+.10),1.6,z,M.dark,car);}box(.06,.055,len-.2,side*(w/2+.05),1.22,0,L.cream,car);}
for(let z of [-2.5,0,2.5]){box(1.23,.19,.95,0,2.94,z,M.edge,car,.06);for(let i=0;i<4;i++)box(1.1,.025,.045,0,3.047,z+(i-1.5)*.17,M.dark,car);}
for(let end of [-1,1]){box(w-.12,1.59,.13,0,1.81,end*(len/2+.004),trim,car,.05);box(w-.55,.75,.06,0,2.10,end*(len/2+.08),M.glass,car,.04);box(.07,.8,.04,0,2.10,end*(len/2+.12),L.rail,car);for(let side of [-1,1]){const lm=lead&&end===1?ledMat:mat('#aa604d',{emissive:'#da482b',emissiveIntensity:.5});mesh(new T.SphereGeometry(.115,8,6),lm,side*.77,1.48,end*(len/2+.12),car);}if(lead&&end===1){const badge=mesh(new T.CircleGeometry(.27,24),roundMat,0,2.19,end*(len/2+.145),car);if(type!=='subway')badge.visible=false;glow(-.77,1.48,end*(len/2+.23),2,.35,car,'#ffeab6');glow(.77,1.48,end*(len/2+.23),2,.35,car,'#ffeab6');}}
if(type!=='subway'&&lead){box(2.43,.62,1.65,0,1.16,3.22,L.red,car,.12);box(.82,.34,.73,0,3.02,1.7,L.iron,car,.08);}consolidate(car,null);return car;}
const trains=[];function makeTrain(type,curve,count,u,speed,dir){const tr={type,curve,length:curve.getLength(),cars:[],u,speed,dir,hold:0};for(let i=0;i<count;i++){let c=trainCar(type,i===0,i);railwayMoving.add(c);tr.cars.push(c)}trains.push(tr);return tr;}
const seven=makeTrain('subway',mainCurve,6,.137,3.2,1),local=makeTrain('local',localCurve,4,.30,2.45,-1);let stationStop=0,bestStop=Infinity;for(let i=0;i<2000;i++){const p=mainCurve.getPointAt(i/2000),d=p.distanceToSquared(new T.Vector3(-36,5.5,68));if(d<bestStop){bestStop=d;stationStop=i/2000;}}
// Headlights cast a small pool on the track ahead of the lead carriage.
const trainHeadlamps=[];for(let tr of trains){const light=new T.SpotLight('#ffe4a8',40,24,.25,.65,1.5);light.position.set(0,1.85,3.65);const target=new T.Object3D();target.position.set(0,0,17);tr.cars[0].add(target);light.target=target;tr.cars[0].add(light);trainHeadlamps.push(light);}
// Painted taxis and a city bus move through the street grid.
function motorVehicle(bus=false){const g=new T.Group(),color=bus?mat('#b8c9c1'):mat(pick(['#dbb254','#be7056','#728e8b','#c8ba94']));const l=bus?6.5:3.6,w=bus?2.1:1.72;box(w,bus?1.65:.85,l,0,bus?1.32:.89,0,color,g,.15);box(w*.86,bus?.8:.62,l*.57,0,bus?1.78:1.43,-.12,M.glass,g,.11);box(w*.92,.12,l*.6,0,bus?2.23:1.80,-.12,color,g,.04);for(let side of [-1,1])for(let end of [-1,1]){let wh=mesh(new T.CylinderGeometry(.3,.3,.15,12),M.dark,side*w*.49,.38,end*l*.32,g);wh.rotation.z=PI/2;}if(bus){for(let z=-2.6;z<2.7;z+=.77)for(let side of [-1,1])box(.04,.72,.61,side*(w/2+.02),1.77,z,M.glass,g,.02);box(w+.02,.2,l-.1,0,1.0,0,M.navy,g);}else box(.46,.16,.34,0,1.94,-.1,L.cream,g,.03);consolidate(g,null);return g;}
const carCurve=new T.CatmullRomCurve3([new T.Vector3(18,1.46,-4),new T.Vector3(22,1.46,-8),new T.Vector3(66,1.46,-8),new T.Vector3(70,1.46,-4),new T.Vector3(70,1.46,21),new T.Vector3(66,1.46,25),new T.Vector3(22,1.46,25),new T.Vector3(18,1.46,21)],true,'centripetal');carCurve.arcLengthDivisions=1200;const vehicles=[];for(let i=0;i<5;i++){let g=motorVehicle(i===0);railwayMoving.add(g);vehicles.push({g,u:i/5,speed:i===0?1.05:1.45})}
function updateRailway(dt,t){for(let tr of trains){if(trainsRunning){if(tr.hold>0)tr.hold-=dt;else{let old=tr.u;tr.u=(tr.u+tr.speed*dt/tr.length*tr.dir+1)%1;if(tr===seven&&old<stationStop&&tr.u>=stationStop){tr.u=stationStop;tr.hold=6;}}}const gap=tr.type==='subway'?7.66:6.86;for(let i=0;i<tr.cars.length;i++){let u=(tr.u-i*gap/tr.length*tr.dir+1)%1,p=tr.curve.getPointAt(u),d=tr.curve.getTangentAt(u).multiplyScalar(tr.dir);tr.cars[i].position.copy(p);tr.cars[i].lookAt(p.clone().add(d));}}
for(let v of vehicles){if(trainsRunning)v.u=(v.u+v.speed*dt/carCurve.getLength())%1;let p=carCurve.getPointAt(v.u),d=carCurve.getTangentAt(v.u);v.g.position.copy(p);v.g.lookAt(p.clone().add(d));}
for(let h of trainHeadlamps)h.intensity=lerp(0,60,night);for(let r of waterRipples){r.m.material.opacity=(.18+Math.sin(t*.9+r.phase)*.055);let k=1+Math.sin(t*.6+r.phase)*.13;r.m.scale.set(k,k*.55,1)}
}

// A different rally plan is sampled from time, never from frame count.
let rallyPlan=queensRally(0);
const aim=new T.Quaternion(),swing=new T.Quaternion(),inverseUpper=new T.Quaternion(),rest=new T.Quaternion().setFromEuler(new T.Euler(-.18,.12,0)),up=new T.Vector3(0,1,0),reach=new T.Vector3(),toward=new T.Vector3(),offset=new T.Vector3();
function posePlayer(p,t){
const motion=queensFootwork(rallyPlan,p.id,t),hit=motion.nearest,phase=motion.phase,weight=1-T.MathUtils.smoothstep(Math.abs(phase),.23,.72);
const serving=hit.serve&&Math.abs(phase)<1.35,load=serving?Math.sin(clamp((phase+1.2)/1.1,0,1)*PI):0,jump=serving?.15*Math.exp(-Math.pow(phase/.22,2)):0;
const split=.04*Math.exp(-Math.pow((phase+.5)/.16,2)),crouch=.035+.085*load+split;
p.g.position.y=1.36-crouch+jump;p.upper.rotation.set(-.07*Math.sin(phase*4)*weight,.54*Math.sin(clamp(phase/.50,-1,1)*PI/2)*weight,.025*Math.sin(motion.step)*motion.moving);
const dy=motion.p[1]-(p.g.position.y+1.25),horizontal=Math.sqrt(Math.max(.02,p.reach.lengthSq()-dy*dy)),backhand=hit.stroke==='backhand',hand=motion.hand*.84;
offset.set(p.arm.position.x+hand*horizontal,0,horizontal*Math.sqrt(1-hand*hand)).applyAxisAngle(up,p.g.rotation.y);
p.g.position.x=motion.p[0]-offset.x;p.g.position.z=motion.p[2]-offset.z;
for(const leg of p.legs){const step=Math.sin(motion.step+(leg.side>0?PI:0)),z=step*.17*motion.moving,lift=Math.max(0,Math.cos(motion.step+(leg.side>0?PI:0)))*.10*motion.moving,down=.63-(.115+crouch+lift),a=.27,b=.25;
const knee=Math.acos(clamp((down*down+z*z-a*a-b*b)/(2*a*b),-.98,.999)),hip=Math.atan2(-z,down)-Math.atan2(b*Math.sin(knee),a+b*Math.cos(knee));leg.hip.rotation.x=hip;leg.knee.rotation.x=knee;leg.foot.rotation.x=-hip-knee;leg.hip.position.x=leg.side*(.15+split);}
p.arm.quaternion.copy(rest);
if(weight>0){toward.fromArray(hit.p).sub(p.g.position).applyAxisAngle(up,-p.g.rotation.y).sub(p.upper.position).applyQuaternion(inverseUpper.copy(p.upper.quaternion).invert()).sub(p.arm.position);aim.setFromUnitVectors(reach.copy(p.reach).normalize(),toward.normalize());swing.setFromAxisAngle(up,clamp(phase/.4,-1,1)*(backhand?-1:1)*1.02);aim.premultiply(swing);p.arm.quaternion.slerp(aim,weight);}
p.left.rotation.set(serving?-2.6*Math.sin(clamp((t-.15)/1.5,0,1)*PI):backhand&&weight>.2?-.6*weight:-.17,0,backhand?-.38*weight:.1*weight);
p.shadow.position.set(p.g.position.x,1.348,p.g.position.z);p.shadow.scale.set(1+jump,.70+jump,1);p.shadow.material.opacity=.21-jump*.4;
}
function resetPoint(overflow=0){rallyPlan=queensRally(Math.max(0,rally-1));matchWon=false;matchStart=time-overflow;matchTime=overflow;betweenRallies=false;celebrateAt=-100;confetti.visible=false;trails.forEach(m=>m.visible=false);posePlayer(p1,overflow);posePlayer(p2,overflow);ball.position.fromArray(queensBall(rallyPlan,overflow));ball.visible=true;bounceMark.visible=false;}
function updateMatch(dt){
if(!playing){if(!matchWon){posePlayer(p1,0);posePlayer(p2,0);ball.position.fromArray(queensBall(rallyPlan,0));ball.visible=true;}return;}
if(dt===0)return;
matchTime=time-matchStart;let t=matchTime;
while(watching&&t>=rallyPlan.duration){const overflow=t-rallyPlan.duration;rally++;resetPoint(overflow);t=overflow;drawScore('rally',rally);}
ball.position.fromArray(queensBall(rallyPlan,t));ball.visible=t<rallyPlan.end+.5;
posePlayer(p1,t);posePlayer(p2,t);
const bounce=rallyPlan.bounces.find(b=>t>=b.t&&t-b.t<.28);bounceMark.visible=!!bounce;
if(bounce){const age=(t-bounce.t)/.28;bounceMark.position.set(bounce.p[0],1.35,bounce.p[2]);bounceMark.scale.setScalar(1+age*2);bounceMark.material.opacity=(1-age)*.42;}
trails.forEach((m,i)=>{m.visible=!reduced&&t>1.65&&t<rallyPlan.end;m.position.fromArray(queensBall(rallyPlan,Math.max(0,t-(i+1)*.012)));});
if(t>rallyPlan.end&&!matchWon&&!betweenRallies){if(watching){betweenRallies=true;drawScore('ready',rally);}else{matchWon=true;celebrateAt=time;confetti.visible=true;drawScore('win');}}
if(matchWon){const winner=rallyPlan.contacts.at(-1).player?p2:p1;winner.arm.rotation.set(0,0,-2.5);winner.left.rotation.set(0,0,2.5);winner.g.position.y=1.36+Math.abs(Math.sin(t*5))*.16;}
if(!watching&&t>rallyPlan.end+6.1){playing=false;for(const p of[p1,p2]){p.arm.rotation.set(0,0,0);p.left.rotation.set(0,0,0);}bounceMark.visible=false;}
}

let time=0,night=0,roofLift=0,roofTarget=0,lastRoofVisible=true;
let playing=false,watching=false,rally=0,betweenRallies=false,matchStart=0,matchWon=false,celebrateAt=-100,matchTime=0;
function tick(dt,n,paused){
const delta=paused?0:dt;time+=delta;night=n;trainsRunning=!paused;
const ease=1-Math.exp(-dt*5.5);updateRailway(delta,time);
roofLift=lerp(roofLift,roofTarget,ease);roof.position.y=roofLift*25;roof.position.z=-roofLift*8;roof.visible=roofLift<.965;
if(Math.abs(roofLift-roofTarget)>.003||lastRoofVisible!==roof.visible){renderer.shadowMap.needsUpdate=true;lastRoofVisible=roof.visible;}
const opacity=clamp(1-roofLift*1.12,0,1);M.roof.transparent=roofLift>.01;M.roof.opacity=opacity;M.roofMetal.transparent=roofLift>.01;M.roofMetal.opacity=opacity;
ambient.intensity=lerp(1.6,.64,night);sun.intensity=lerp(3.1,.38,night);sun.color.set(night>.5?'#d5e4f3':'#fff0cf');fill.intensity=lerp(.6,.69,night);courtLight.intensity=lerp(25,155,night);renderer.toneMappingExposure=lerp(1.16,1.26,night);
for(const [m,strength] of glowMaterials)m.emissiveIntensity=lerp(.12,strength,night);
for(const g of glows)g.m.material.opacity=g.opacity*night*(g.m.parent===roof?opacity:1);
for(const m of pools)m.material.opacity=night;dust.material.opacity=.25*night;
dt=delta;
if(!reduced){for(let f of flags){let a=f.g.attributes.position.array;for(let i=0;i<a.length;i+=3){let x=f.original[i];a[i+2]=Math.sin(x*2.1-time*2.5+f.phase)*.18*(x/2.8)+Math.sin(x*4.3-time*3)*.04*(x/2.8);a[i+1]=f.original[i+1]-.1*(x/2.8)+Math.sin(x*2-time*1.8)*.035*x;}f.g.attributes.position.needsUpdate=true;f.g.computeVertexNormals();}for(let i=0;i<dustN;i++){dustPos[i*3]+=.012*dt*Math.sin(time+i);dustPos[i*3+1]+=.015*dt;if(dustPos[i*3+1]>34)dustPos[i*3+1]=3}dustG.attributes.position.needsUpdate=true;}
updateMatch(dt);ballShadow.visible=ball.visible;ballShadow.position.set(ball.position.x,1.347,ball.position.z);ballShadow.material.opacity=clamp(.4-(ball.position.y-1.4)*.075,.07,.38);
const ct=time-celebrateAt;if(ct<11&&confetti.visible){for(let i=0;i<confettiCount;i++){let a=confettiData[i],age=Math.max(0,ct-(i%7)*.09);const y=a.y+a.vy*(1-Math.exp(-age*.5))*2-age*2.5;dummy.position.set(a.x+a.vx*age+Math.sin(age*2+a.spin)*.5,Math.max(1.43,y),a.z+a.vz*age);dummy.rotation.set(a.spin+age*2.1,a.spin+age*1.2,age*1.7);dummy.scale.setScalar(a.s);dummy.updateMatrix();confetti.setMatrixAt(i,dummy.matrix);}confetti.instanceMatrix.needsUpdate=true;}else confetti.visible=false;

}
tick(0,0,false);await step('Lighting the little world…');
const indexed=new Set();scene.traverse(node=>{if(node.isMesh&&!node.userData.queensAnimated&&!indexed.has(node.geometry)){indexed.add(node.geometry);indexQueensGeometry(T,node.geometry);}});
const storage=shareQueensGeometry(scene);
// These construction collections share the factory's closure with tick().
// Empty them so they cannot retain replaced buffers or instance descriptions.
indexed.clear();batches.clear();textureCanvases.length=0;
return {trains,seven,local,stationStop,seats,spectators,roof,tick,
 setRoof:open=>{roofTarget=open?1:0;},
 setScore(score){matchScore=score;drawScore();},
 setWatching(on){if(watching===on)return;watching=on;playing=on;rally=on?1:0;resetPoint();if(on)roofTarget=0;drawScore(on?'rally':'point',rally);},
 play(){if(playing&&!watching)return;watching=false;playing=true;rally=0;betweenRallies=false;resetPoint();drawScore('rally');roofTarget=1;},
 stats:()=>({seats,spectators,storage,playing,watching,rally,matchTime,matchWon,pointEnds:rallyPlan.end,pointDuration:rallyPlan.duration,server:rallyPlan.server,score:matchScore,roofLift,roofTarget,night,stationStop,trains:trains.map(t=>({position:t.u,cars:t.cars.length,hold:t.hold}))})
};
